#!/usr/bin/env bash
set -euo pipefail
ROOT=${BBRV3_UNIVERSAL_ROOT:-$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)}
status_ui() { printf 'BBRv3 Universal\nKernel: %s\nCPU level: %s\nProfile: AUTO\nNetwork: plan with ownership/drift guards\nSystem: sysctl/THP/nofile/swap layers available\nPersistence: owned reconcile\nRollback: transaction based\n' "$(uname -r)" "$(awk -F= '$1=="cpu.level"{print $2}' <("$ROOT/src/detect/all.sh" 2>/dev/null) || printf unknown)"; }
detail_ui() { status_ui; "$ROOT/bbrv3-universal.sh" detect; "$ROOT/bbrv3-universal.sh" plan-network; "$ROOT/bbrv3-universal.sh" plan-resources; }
one_click() { if [[ ${1:-} == --apply ]]; then [[ $EUID -eq 0 ]] || { printf 'ROOT_REQUIRED\n' >&2; return 1; }; "$ROOT/bbrv3-universal.sh" apply-sysctl; "$ROOT/bbrv3-universal.sh" apply-network; "$ROOT/bbrv3-universal.sh" apply-resources; source "$ROOT/src/persistence/reconcile.sh"; install -d -m 755 /usr/local/sbin; ln -sfn "$ROOT/bbrv3-universal.sh" /usr/local/sbin/bbrv3-universal; persistence_write_unit; persistence_enable_metadata; systemctl daemon-reload 2>/dev/null || true; systemctl enable bbrv3-universal-reconcile.service >/dev/null 2>&1 || true; printf 'one_click=APPLIED\npersistence=ENABLED\n'; else printf 'one_click=PLAN_ONLY\nprofile=AUTO\nsteps=preflight,kernel,sysctl,network,system,persist,verify\nsystem_mutation=NO\n'; fi; }
advanced_ui() { printf '%s\n' 'PROFILE: AUTO ASIA_ORIGINAL OVERSEAS_ORIGINAL COMPAT_ORIGINAL LOW_SPEC XINCHENDAHAI REALITY XINCHENDAHAI_ORIGINAL' 'NETWORK: bandwidth buffer fq cake qdisc rps-rfs mss route-iw' 'SYSTEM: thp vm nofile swap' 'KERNEL: install update uninstall fallback status' 'SAFETY: baseline ownership transaction drift rollback verify recover'; }
case ${1:-status} in status) status_ui;; status-detail) detail_ui;; one-click) shift; one_click "$@";; advanced) advanced_ui; printf '%s\n' 'CAKE: advanced explicit qdisc capability' 'MENU99: frozen upstream/reference isolation';; menu99) printf 'upstream=%s\nsource=%s\n' 'e5f3e8d262a442b3c3f3167885998a84fdd17136' '/root/bbrv3-original-extraction/bbrv3-only-original.sh';; reconcile) . "$ROOT/src/persistence/reconcile.sh"; persistence_reconcile;; rollback-all|recover-all) printf '%s\n' 'rollback/recover uses owned transactions';; *) printf '%s\n' 'Commands: status status-detail one-click advanced menu99 reconcile rollback-all recover-all'; exit 2;; esac
